result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/scheduler/providers.py", "content": """"Weekly provider templates.

A template maps weekday (0=Monday .. 6=Sunday) to a tuple of sessions.
Sessions are half-open intervals [start, end); anything between two
sessions (e.g. lunch) is structurally unbookable because no slot can
ever be generated or validated there.
"""

from __future__ import annotations

from dataclasses import dataclass
from datetime import date, datetime, time

# Sessions are given as "HH:MM" strings for readability; parsed once.


@dataclass(frozen=True)
class ProviderTemplate:
    provider_id: str
    slot_minutes: int
    daily_cap: int = 14
    # weekday -> ((start_time, end_time), ...)
    sessions: dict[int, tuple[tuple[time, time], ...]] = None  # type: ignore[assignment]

    def __post_init__(self) -> None:
        if self.sessions is None:
            object.__setattr__(self, "sessions", {})
        parsed: dict[int, tuple[tuple[time, time], ...]] = {}
        for wd, sess in self.sessions.items():
            parsed[wd] = tuple(
                (_t(s), _t(e)) for s, e in sess
            )
        object.__setattr__(self, "sessions", parsed)

    def sessions_on(self, d: date) -> tuple[tuple[time, time], ...]:
        return self.sessions.get(d.weekday(), ())

    def slot_bounds(self, when: datetime) -> tuple[datetime, datetime]:
        """End of the slot starting at `when`."""
        from datetime import timedelta

        end = when + timedelta(minutes=self.slot_minutes)
        return when, end


def _t(hhmm: str) -> time:
    h, m = hhmm.split(":")
    return time(int(h), int(m))


