All mutating operations run inside a BEGIN IMMEDIATE transaction so that
check-then-insert sequences are atomic even under concurrent processes.
"""

from __future__ import annotations

import sqlite3
from datetime import date, datetime, time, timedelta
from pathlib import Path

from .db import connect
from .models import (
    Booking,
    CapReachedError,
    DoubleBookingError,
    NotFoundError,
    OutsideTemplateError,
    PatientConflictError,
    SchedulerError,
    Slot,
    UnknownProviderError,
)
from .providers import DEFAULT_PROVIDERS, ProviderTemplate

ISO_FMT = "%Y-%m-%dT%H:%M:%S"


def _iso(dt: datetime) -> str:
    return dt.strftime(ISO_FMT)


def _as_datetime(x: datetime | str) -> datetime:
    if isinstance(x, datetime):
        return x.replace(tzinfo=None)
    return datetime.strptime(x, ISO_FMT)


class Scheduler:
    def __init__(
        self,
        db_path: str | Path = "scheduler.db",
        providers: dict[str, ProviderTemplate] | None = None,
    ) -> None:
        self.providers = providers if providers is not None else DEFAULT_PROVIDERS
        self.con = connect(db_path)

    def close(self) -> None:
        self.con.close()

    # ------------------------------------------------------------------ #
    # Availability
    # ------------------------------------------------------------------ #

    def slots_for_date(self, provider_id: str, d: date) -> list[Slot]:
        """Every slot the template *could* offer on `d` (booked or not)."""
        tmpl = self._template(provider_id)
        length = timedelta(minutes=tmpl.slot_minutes)
        out: list[Slot] = []
        for sess_start, sess_end in tmpl.sessions_on(d):
            cur = datetime.combine(d, sess_start)
            end = datetime.combine(d, sess_end)
            while cur + length <= end:
                out.append(Slot(provider_id, cur, cur + length))
                cur += length
        return out

    def available(self, provider_id: str, d: date | str) -> list[Slot]:
        """Free, bookable slots for a provider on a date.

        Excludes actively booked slots; empty if the daily cap is reached
        or the provider has no session that weekday (lunch gap included).
        """
        if isinstance(d, str):
            d = date.fromisoformat(d)
        tmpl = self._template(provider_id)

        cap_hit = self._active_count(provider_id, d.isoformat()) >= tmpl.daily_cap
        booked_starts = {
            r["start_ts"]
            for r in self.con.execute(
                "SELECT start_ts FROM bookings "
                "WHERE provider_id=? AND status='active' AND substr(start_ts,1,10)=?",
                (provider_id, d.isoformat()),
            )
        }
        if cap_hit:
            return []
        return [s for s in self.slots_for_date(provider_id, d) if _iso(s.start) not in booked_starts]

    # ------------------------------------------------------------------ #
    # Booking
    # ------------------------------------------------------------------ #

    def book(self, provider_id: str, when: datetime | str, patient_id: str) -> int:
        """Book a slot. Returns booking id. Raises on any constraint violation."""
        tmpl = self._template(provider_id)
        start, end = tmpl.slot_bounds(_as_datetime(when))

        if not self._within_template(tmpl, start, end):
            raise OutsideTemplateError(
                f"{provider_id} {start.isoformat()}..{end.isoformat()} is outside "
                f"template sessions / misaligned / in lunch gap"
            )

        try:
            self.con.execute("BEGIN IMMEDIATE")
            # 1) Patient must not hold an overlapping booking at another provider.
            clash = self.con.execute(
                "SELECT id, provider_id FROM bookings "
                "WHERE patient_id=? AND status='active' "
                "AND start_ts < ? AND ? < end_ts",
                (patient_id, _iso(start), _iso(end)),
            ).fetchone()
            if clash is not None:
                raise PatientConflictError(
                    f"patient {patient_id!r} already holds booking #{clash['id']} "
                    f"with {clash['provider_id']}"
                )
            # 2) Daily cap of active visits per provider per calendar day.
            day = start.date().isoformat()
            count = self._active_count_in_tx(provider_id, day)
            if count >= tmpl.daily_cap:
                raise CapReachedError(
                    f"{provider_id} reached daily cap {tmpl.daily_cap} on {day}"
                )
            # 3) Insert; the partial unique index is the final authority.
            try:
                cur = self.con.execute(
                    "INSERT INTO bookings (provider_id, patient_id, start_ts, end_ts, status) "
                    "VALUES (?, ?, ?, ?, 'active')",
                    (provider_id, patient_id, _iso(start), _iso(end)),
                )
            except sqlite3.IntegrityError as exc:
                raise DoubleBookingError(
                    f"slot {provider_id} @{_iso(start)} already booked"
                ) from exc
            self.con.commit()
            return int(cur.lastrowid)
        except SchedulerError:
            self.con.rollback()
            raise
        except Exception:
            self.con.rollback()
            raise

    def cancel(self, booking_id: int) -> None:
        """Cancel an active booking. Raises NotFoundError if none exists."""
        try:
            self.con.execute("BEGIN IMMEDIATE")
            cur = self.con.execute(
                "UPDATE bookings SET status='cancelled' WHERE id=? AND status='active'",
                (int(booking_id),),
            )
            if cur.rowcount == 0:
                raise NotFoundError(f"no active booking with id={booking_id}")
            self.con.commit()
        except Exception:
            self.con.rollback()
            raise

    def get_booking(self, booking_id: int) -> Booking | None:
        row = self.con.execute(
            "SELECT id, provider_id, patient_id, start_ts, end_ts FROM bookings WHERE id=?",
            (int(booking_id),),
        ).fetchone()
        if row is None:
            return None
        return Booking(
            id=row["id"],
            provider_id=row["provider_id"],
            patient_id=row["patient_id"],
            start=datetime.strptime(row["start_ts"], ISO_FMT),
            end=datetime.strptime(row["end_ts"], ISO_FMT),
        )

    # ------------------------------------------------------------------ #
    # Internals
    # ------------------------------------------------------------------ #

    def _template(self, provider_id: str) -> ProviderTemplate:
        tmpl = self.providers.get(provider_id)
        if tmpl is None:
            raise UnknownProviderError(f"unknown provider {provider_id!r}")
        return tmpl

    def _within_template(self, tmpl: ProviderTemplate, start: datetime, end: datetime) -> bool:
        if start.date() != end.date() - timedelta(days=(1 if end.time() == time(0, 0) else 0)):
            pass  # same-day enforced below anyway via session containment
        for sess_start, sess_end in tmpl.sessions_on(start.date()):
            s_lo = datetime.combine(start.date(), sess_start)
            s_hi = datetime.combine(start.date(), sess_end)
            offset_min = (start - s_lo).total_seconds() / 60.0
            if (
                s_lo <= start
                and end <= s_hi
                and offset_min % tmpl.slot_minutes == 0  # grid alignment
            ):
                return True
        return False

    def _active_count(self, provider_id: str, day_iso: str) -> int:
        return int(
            self.con.execute(
                "SELECT COUNT(*) AS n FROM bookings "
                "WHERE provider_id=? AND status='active' AND substr(start_ts,1,10)=?",
                (provider_id, day_iso),
            ).fetchone()["n"]
        )

    def _active_count_in_tx(self, provider_id: str, day_iso: str) -> int:
        row = self.con.execute(
            "SELECT COUNT(*) AS n FROM bookings "
            "WHERE provider_id=? AND status='active' AND substr(start_ts,1,10)=?",
            (provider_id, day_iso),
        ).fetchone()
        return int(row["n"])
"})
