from __future__ import annotations

from dataclasses import dataclass
from datetime import datetime, timedelta


class SchedulerError(Exception):
    """Base class for all scheduler constraint violations."""


class UnknownProviderError(SchedulerError):
    pass


class OutsideTemplateError(SchedulerError):
    """Slot is off-template: wrong weekday, off hours, lunch gap, or misaligned grid."""


class DoubleBookingError(SchedulerError):
    """Another active booking already occupies this provider+slot."""


class CapReachedError(SchedulerError):
    """Provider's daily cap of active visits would be exceeded."""


class PatientConflictError(SchedulerError):
    """Patient already holds an overlapping booking (any provider)."""


class NotFoundError(SchedulerError):
    """No active booking with the given id."""


@dataclass(frozen=True)
class Slot:
    provider_id: str
    start: datetime
    end: datetime

    def __str__(self) -> str:
        return f"{self.provider_id} {self.start:%Y-%m-%d %H:%M}-{self.end:%H:%M}"

    @property
    def minutes(self) -> int:
        return int((self.end - self.start).total_seconds() // 60)


@dataclass(frozen=True)
class Booking:
    id: int
    provider_id: str
    patient_id: str
    start: datetime
    end: datetime

    @property
    def minutes(self) -> int:
        return int((self.end - self.start).total_seconds() // 60)


def slot_length_minutes(slot: Slot | Booking) -> int:
    return int((slot.end - slot.start).total_seconds() // 60) or 1


def overlaps(a_start: datetime, a_end: datetime, b_start: datetime, b_end: datetime,
             epsilon: timedelta = timedelta(0)) -> bool:
    """Half-open interval overlap; touching endpoints do NOT overlap."""
    return a_start < b_end - epsilon and b_start < a_end - epsilon
